2	// Input is a plain JS string (guaranteed ASCII); output uses the shared
3	// tagged-value contract:
4	//   bytes -> { kind: 'bytes', data: string }
5	//   int   -> { kind: 'int', value: BigInt }
6	//   list  -> { kind: 'list', items: [value, ...] }
7	//   dict  -> { kind: 'dict', entries: [[keyValue, valValue], ...] }
8	
9	export function decode(s) {
10	  const [value, pos] = parseValue(s, 0);
11	  if (pos !== s.length) {
12	    throw new Error('TypeError: Malformed input.');
13	  }
14	  return value;
15	}
