17	function parseValue(s, pos) {
18	  if (pos >= s.length) {
19	    throw new Error('IndexError: index out of range');
20	  }
21	  const ch = s[pos];
22	
23	  if (ch === 'i') {
24	    const m = /^i(-?\d+)e/.exec(s.slice(pos));
25	    if (m === null) {
26	      throw new Error("AttributeError: 'NoneType' object has no attribute 'group'");
27	    }
28	    return [{ kind: 'int', value: BigInt(m[1]) }, pos + m[0].length];
29	  }
30	
31	  if (ch >= '0' && ch <= '9') {
32	    const m = /^(\d+):/.exec(s.slice(pos));
33	    if (m === null) {
34	      throw new Error("AttributeError: 'NoneType' object has no attribute 'group'");
35	    }
36	    const start = pos + m[0].length;
37	    const n = parseInt(m[1], 10);
38	    // Python slice semantics: fewer than n remaining chars is not an error.
39	    const data = s.slice(start, start + n);
40	    return [{ kind: 'bytes', data }, start + data.length];
41	  }
42	
43	  if (ch === 'l') {
44	    pos += 1;
45	    const items = [];
46	    for (;;) {
