48	        throw new Error('IndexError: index out of range');
49	      }
50	      if (s[pos] === 'e') {
51	        return [{ kind: 'list', items }, pos + 1];
52	      }
53	      const [v, next] = parseValue(s, pos);
54	      items.push(v);
55	      pos = next;
